-- Current state for explicitly active v3 package targets only.
-- Execute in loucka_reconstruction via Weather MCP READ-ONLY SQL.
-- This query has no staging/apply statements and does not read protected 2021 targets.
SELECT dateTime,usUnits,`interval`,outTemp,outHumidity,rain,rainRate,windSpeed,windGust,windDir,barometer
FROM archive
WHERE dateTime IN (
1373319000,1373319600,1373320200,1373320800,1546297200,1559239800,
1582349400,1582354200,1582362300,1582365300,1582366200,1582367100,1582368000,1582373700,1582380000,1582389600,1582390200,1582410000,1582410900,1583098800,1583103900,1583143200,1583143800,1589361600,1589367600,1589368200,1589377500,1589378400,1592301000,1593123000,1593794100,1593795600,1593796200,1594410000,1596384600,1598789100,1598789400,1603181700,1603182000,1603185600,1603185900,1603188600,1607100600,1607102700,1607103000,1607212800,1607213100,1607215800,1607217300,1607311200,1607314800,1607317200,1607524500,1607524800,1607525100,1607525400
)
ORDER BY dateTime;

-- Check history for the 65 proposed timestamp-variable pairs.
-- Active proposed pairs currently have no events; this separate all-field query
-- detects existing context events on those timestamps (e.g. 2018 outTemp).
SELECT target_time,variable,state,COUNT(*) AS event_count,MAX(created_at) AS latest_event
FROM reconstruction_changes
WHERE target_time IN (
1373319000,1373319600,1373320200,1373320800,1546297200,1559239800,
1582349400,1582354200,1582362300,1582365300,1582366200,1582367100,1582368000,1582373700,1582380000,1582389600,1582390200,1582410000,1582410900,1583098800,1583103900,1583143200,1583143800,1589361600,1589367600,1589368200,1589377500,1589378400,1592301000,1593123000,1593794100,1593795600,1593796200,1594410000,1596384600,1598789100,1598789400,1603181700,1603182000,1603185600,1603185900,1603188600,1607100600,1607102700,1607103000,1607212800,1607213100,1607215800,1607217300,1607311200,1607314800,1607317200,1607524500,1607524800,1607525100,1607525400
)
GROUP BY target_time,variable,state
ORDER BY target_time,variable,state;
